        has_design_system: Boolean(ds?.designSystemTemplateId),
        suggestions: buildOfferSuggestions(
          brand,
          designs,
          deliverables.filter((deliverable) => rawDeals.some((deal) => deal.id === deliverable.deal_id && deal.brand_id === brand.id && deal.stage !== "lost")).map((deliverable) => deliverable.asset_type)
        ),
        // v45 (DIATTA): computed health (manual override wins) + touchpoint count.
