        duration: { type: "number", description: "Clip length in seconds: any integer 2-10 (default 5). Runway caps every generation at 10s \u2014 for longer pieces, generate scenes separately" },
        ratio: { type: "string", description: "Output aspect ratio: 1280:720 (default), 720:1280, 960:960, 1104:832, 832:1104, 1584:672, 672:1584" },
