              height: { type: "number" },
              text: { type: "string" },
              tag: { type: "string", enum: ["div", "span", "p", "h1", "h2", "h3", "h4", "h5", "h6"] },
              src: { type: "string" },
              alt: { type: "string" },
              svg: { type: "string" },
              style: { type: "object" }
