  const { getSupabaseAdmin: getSupabaseAdmin2, getSupabase: getSupabase2 } = await sbService();
  const sb = getSupabaseAdmin2() || getSupabase2();
  if (!sb) return [];
  const cutoff = new Date(Date.now() - minAgeMs).toISOString();
  const { data: jobs } = await sb.from("segment_jobs").select("id").eq("status", "queued").lt("updated_at", cutoff).order("created_at", { ascending: true }).limit(limit);
